+import { expect, test } from 'bun:test';
+import { formatRelative } from './format';
+
+test('says just now under a minute', () => {
+  expect(formatRelative(new Date(Date.now() - 30_000))).toBe('just now');
+});
+
+test('counts whole minutes after that', () => {
+  expect(formatRelative(new Date(Date.now() - 5 * 60_000))).toBe('5 minutes ago');
+});
